sp_page.css:
\// each column has a flex-item classs

@media (max-width: 992px) {
  .sp-page-root.page {
    height: 100%;
  }
}
  
.flex-item {
  width: 50%;
  position: relative;
}

.v5001b062d7101200b0b044580e6103eb > .panel , .flex-item .vfd1f4ec347730200ba13a5554ee490c0 > .panel-shift > .panel {
  position: absolute;
  top: 0;
  bottom: 0;
  right: 0;
  left: 0;
  margin: 0;
  overflow: hidden;
  border-radius: 0;
  display: flex;
  flex-direction: column;
  height: 100%;

  > .panel-body {
    overflow: scroll;
    -webkit-overflow-scrolling: touch;
    flex-grow: 1;
  }

  > .panel-heading, .panel-footer {
    flex-shrink: 0;
  }

  > .panel-heading {
    height: 52px;
  }
}

footer {
	position: static;
}

.fill-section-contained {
  position: absolute;
  top: 111px;
  bottom: 0;
  left: 0;
  right: 0;
  overflow: hidden;
}

.v5001b062d7101200b0b044580e6103eb .th-title {
  display: inline-block;
  color: #2E551B;
}

.panel-heading {
  height: auto !important;
}

.v5001b062d7101200b0b044580e6103eb .table > thead > tr > th {
  border-right: .1rem solid #555;
}
